    [SYSTEM_CLOCK.TABLE, TABLE_CLOCK_IDS],
    [SYSTEM_CLOCK.NEAR, NEAR_CLOCK_IDS],
    [SYSTEM_CLOCK.CALENDAR, CALENDAR_CLOCK_IDS],
